"""Builds jobshield-ai-v2.html by injecting data generated by backend/gen_data.py"""
import csv, json
from pathlib import Path
here = Path(__file__).parent
rows = list(csv.DictReader(open(here.parent/"backend/data/sample_jobs.csv", encoding="utf-8")))
ds = [[r["title"]+" "+r["description"], int(r["label"])] for r in rows[0::2]]
pool = rows[1::2]; want = ["0","1"]*0
fake_types = ["advance_fee","data_theft","task","mlm","cheque","advance_fee"]; samples = []
for t in fake_types:
    r = next(x for x in pool if x["scam_type"]==t and x not in samples); samples.append(r)
samples += [x for x in pool if x["label"]=="0"][:6]
out = [dict(title=r["title"],company=r["company"],site=r["website"],email=r["email"],desc=r["description"],qual="",sal=r["salary"],type="Full-time",loc="",
            url=("https://bit.ly/apply-now" if r["label"]=="1" and len(r["description"])%2 else ""),label=int(r["label"]),scam_type=r["scam_type"]) for r in samples]
html = (here/"template.html").read_text(encoding="utf-8").replace("__DATA__",json.dumps(ds,ensure_ascii=False)).replace("__SAMPLES__",json.dumps(out,ensure_ascii=False))
srows = list(csv.DictReader(open(here.parent/"backend/data/sample_scams.csv", encoding="utf-8")))
sds = [[r["text"],int(r["label"]),r["scam_type"]] for r in srows[0::2]]; sp = srows[1::2]; ss = []
for t in ["phishing","otp","lottery","investment","loan_app","delivery","authority","upi_refund"]:
    ss.append(next(x for x in sp if x["scam_type"]==t))
ss += [x for x in sp if x["label"]=="0"][:5]
ssamp = [dict(text=r["text"],label=int(r["label"]),type=r["scam_type"]) for r in ss]
rules = json.loads((here.parent/"backend/data/scam_rules.json").read_text(encoding="utf-8"))
html = html.replace("__SDATA__",json.dumps(sds,ensure_ascii=False)).replace("__SSAMPLES__",json.dumps(ssamp,ensure_ascii=False)).replace("__SRULES__",json.dumps(rules,ensure_ascii=False))
(here/"scamshield-ai-v4.html").write_text(html,encoding="utf-8"); print("built",len(html)//1024,"KB",len(ds),len(sds),"train rows",len(out),len(ssamp),"samples")
